```cypher
MATCH (so:SalesOrder)-[:IN_TERRITORY]->(:Territory {name:'Southeast'}),
      (so)-[:HAS_LINE]->(p:Product)-[:IN_SUBCATEGORY]->(:Subcategory)-[:IN_CATEGORY]->(:Category {name:'Bikes'})
WHERE date_part('year', so.order_date) = 2023
  AND NOT EXISTS {
    MATCH (so2:SalesOrder)-[:IN_TERRITORY]->(:Territory {name:'United Kingdom'}), (so2)-[:HAS_LINE]->(p)
    WHERE date_part('year', so2.order_date) = 2023
  }
RETURN DISTINCT p.product_number AS product_number;
